export function judgeGameUpdate(opts: {
  family: GameFamily;
  hostname: string;
  facts: GameUpdateFacts;
}): GameUpdateVerdict {
  const { family, hostname, facts: f } = opts;
  const appId = STEAM_APPID[family];

  if (!f.complete) {
    return {
      ok: false,
      reason:
        `the update script did not run to completion on ${hostname} (no end marker), so nothing about ` +
        `this run can be verified — the connection may have dropped or the command timed out. ` +
        `Nothing is being claimed. Re-run it by hand: systemctl status <your ${family} unit>`,
    };
  }

  if (!f.unit) {
    return {
      ok: false,
      reason:
        `no systemd service for ${family} was found on ${hostname}, so nothing was updated and ` +
        `nothing was restarted. Check what the server actually runs with: ` +
        `systemctl list-units --type=service | grep -i ${family}`,
    };
  }

  if (appId && f.steam === "absent") {
    return {
      ok: false,
      reason:
        `steamcmd is not installed on ${hostname}, so the ${family} game files were NOT updated. ` +
        `Auto-update cannot work on this server until it is present: apt-get install -y steamcmd ` +
        `(or reinstall from the ${family} image).`,
    };
  }

  if (appId && f.steam !== "ok") {
    const detail = f.steamErrors.length ? ` steamcmd said: ${f.steamErrors.slice(0, 3).join(" | ")}` : "";
    return {
      ok: false,
      reason:
        `steamcmd did not report a successful update of app ${appId} on ${hostname} ` +
        `(exit ${f.steamRc ?? "unknown"}), so the game files were not updated and the service was ` +
        `left alone.${detail} Re-run by hand: steamcmd +login anonymous +app_update ${appId} validate +quit`,
    };
  }

